set statement_timeout='1500s'; set work_mem='128MB';
\copy (with r as (select platform, product_id, review_id, md5(regexp_replace(lower(content), '[^0-9a-z가-힣]', '', 'g')) h from reviews where char_length(regexp_replace(content, '\s', '', 'g'))>=15), u as (select platform, review_id, h, count(distinct product_id) shared from r group by 1,2,3), g as (select platform, h, count(*) ids, sum(shared) rows from u group by 1,2) , s as (select platform, count(*) filter (where shared>=2) shared_ids, count(*) total_ids from u group by 1) select g.platform, max(s.total_ids) unique_reviews, max(s.shared_ids) same_id_multi_product, sum(ids) filter (where ids>=2) dup_text_diff_id, round(sum(ids) filter (where ids>=2)*100.0/max(s.total_ids),2) dup_pct, count(*) filter (where ids>=2) dup_groups, count(*) filter (where ids>=5) groups_5plus, max(ids) max_ids from g join s using(platform) group by 1 order by 1) to stdout with csv header
